<?php $this->view('page_components/header'); ?>
<?php
// Jedna lista wysyłek (dawniej : Wysyłki, Dokumenty transportowe, Archiwum WZ / CMR / WDT / różnic) : wszystkie dokumenty
// wysyłki w jednym wierszu, filtr « Dokument » (?type=) zamiast osobnych list.
$types = ['' => 'Wszystkie wysyłki', 'wz' => 'WZ', 'cmr' => 'CMR', 'wdt' => 'WDT', 'difference' => 'Z dokumentem różnic',
    'bdo-missing' => 'Bez ewidencji BDO', 'ppwr-missing' => 'Bez raportu PPWR', 'ksef-pending' => 'KSeF : nieprzyjęte'];
$type = isset($types[$docType ?? '']) ? (string) ($docType ?? '') : '';
?>
<div class="page-heading"><div class="page-title"><h3>Wysyłki i dokumenty</h3><p class="text-subtitle text-muted">WZ, CMR, WDT, dokumenty różnic, ewidencja BDO, raport PPWR i KSeF każdej wysyłki — filtr « Dokument » pokazuje jeden rodzaj.</p></div>
<section class="section"><div class="card"><div class="card-body">
    <div class="row g-2 mb-3"><div class="col-md-3"><input class="form-control" id="filterCompany" placeholder="Filtruj po nazwie klienta"></div><div class="col-md-2"><input class="form-control" type="date" id="filterDate"></div>
        <div class="col-md-3"><select class="form-select" id="filterType" aria-label="Dokument"><?php foreach ($types as $value => $label): ?><option value="<?= $value ?>"<?= $value === $type ? ' selected' : '' ?>><?= htmlspecialchars($label) ?></option><?php endforeach; ?></select></div>
        <div class="col-md-2"><button class="btn btn-outline-secondary w-100" type="button" onclick="clearFilters()">Wyczyść</button></div><div class="col-md-2"><button class="btn btn-outline-primary w-100" id="refresh-ksef-statuses" type="button" onclick="refreshKsefStatuses(true)"><i class="bi bi-arrow-clockwise"></i> Statusy KSeF</button></div></div>
    <div class="table-responsive"><table class="table table-hover align-middle" id="generatedDocsTable" data-at-table data-at-table-search="false"><thead><tr><th>Data</th><th>Klient</th><th class="text-end">Dokumenty</th><th>BDO</th><th>PPWR</th><th>KSeF</th></tr></thead><tbody>
    <?php foreach ($generated_docs ?? [] as $row):
        $status = $row['ksef_status'] ?? null;
        $tags = array_filter([(int) $row['id_wz'] ? 'wz' : null, (int) $row['id_cmr'] ? 'cmr' : null, (int) $row['id_wdt'] ? 'wdt' : null, (int) $row['id_diff'] ? 'difference' : null,
            empty($row['packaging_status']) ? 'bdo-missing' : null, empty($row['ppwr_evidence_basis']) ? 'ppwr-missing' : null, $status !== 'accepted' && (int) $row['id_wdt'] ? 'ksef-pending' : null]); ?>
    <tr data-tags="<?= implode(' ', $tags) ?>"><td><?= htmlspecialchars($row['shipment_date']) ?></td><td><?= htmlspecialchars($row['company']) ?></td>
        <td class="text-end"><div class="at-actions"><button class="btn btn-sm btn-primary" onclick="getGrouped(<?= (int)$row['id'] ?>)" type="button">WZ i dokumenty (PDF)</button><div class="at-more"><button type="button" class="at-more-toggle" aria-haspopup="menu" aria-expanded="false" aria-label="Więcej akcji" title="Więcej akcji"><i class="bi bi-three-dots"></i></button><div class="at-more-menu" role="menu" hidden>
            <button type="button" role="menuitem" onclick="getCMR(<?= (int)$row['id_cmr'] ?>)"><i class="bi bi-truck"></i>CMR (PDF)</button>
            <?php if ((int)$row['id_wdt']): ?><button type="button" role="menuitem" onclick="getWDT(<?= (int)$row['id_wdt'] ?>)"><i class="bi bi-receipt"></i>WDT (PDF)</button>
            <a role="menuitem" href="<?= ROOT ?>/communication/compose/wdt/<?= (int)$row['id_wdt'] ?>"><i class="bi bi-envelope"></i>Przygotuj e-mail z WDT</a><?php endif; ?>
            <?php if ((int)$row['id_diff'] !== 0): ?><button type="button" role="menuitem" onclick="getDiff(<?= (int)$row['id_diff'] ?>)"><i class="bi bi-arrow-left-right"></i>Różnice (PDF)</button><?php endif; ?>
            <?php if ($status !== 'accepted' && (int)$row['id_wdt']): ?><a role="menuitem" href="<?= ROOT ?>/wdt-documents/<?= (int)$row['id_wdt'] ?>/products" data-ksef-edit-prices="<?= (int)$row['id'] ?>"><i class="bi bi-pencil"></i>Edytuj ceny WDT</a><?php endif; ?>
        </div></div></div></td>
        <td><?php if (!empty($row['packaging_status'])): ?><?php if (($row['packaging_status'] ?? null) === 'REQUIRES_DATA'): ?><div><span class="badge bg-warning text-dark mb-1">Braki: <?= (int)$row['packaging_issue_count'] ?></span></div><?php endif; ?><button class="btn btn-sm btn-outline-success" onclick="downloadPDF('/ajax/shipments/<?= (int)$row['id'] ?>/documents/packaging')" type="button">BDO (PDF)</button><?php else: ?><button class="btn btn-sm btn-outline-primary" onclick="createBdoEvidence(<?= (int)$row['id'] ?>)" type="button">Utwórz BDO</button><?php endif; ?></td>
        <td><button id="ppwr-action-<?= (int)$row['id'] ?>" class="btn btn-sm <?= empty($row['ppwr_evidence_basis']) ? 'btn-outline-primary' : 'btn-outline-primary' ?>" onclick="<?= empty($row['ppwr_evidence_basis']) ? 'createPpwrEvidence(' . (int)$row['id'] . ')' : 'downloadPpwr(' . (int)$row['id'] . ')' ?>" type="button"><?= empty($row['ppwr_evidence_basis']) ? 'Generuj PPWR' : 'PPWR (PDF)' ?></button><div id="ppwr-status-<?= (int)$row['id'] ?>" class="small <?= empty($row['ppwr_evidence_basis']) ? 'text-muted' : (($row['ppwr_evidence_basis'] === 'CURRENT_DATA_RECONSTRUCTION') ? 'text-warning' : 'text-success') ?>"><?= empty($row['ppwr_evidence_basis']) ? 'Brak raportu' : (($row['ppwr_evidence_basis'] === 'CURRENT_DATA_RECONSTRUCTION') ? 'Dane bieżące' : 'Snapshot wysyłki') ?></div></td>
        <td><?php if ((int)$row['id_wdt']): ?><?php if ($status !== 'accepted'): ?><button class="btn btn-sm btn-outline-primary mb-1" data-ksef-send-button="<?= (int)$row['id'] ?>" onclick="sendToKsef(<?= (int)$row['id'] ?>)" type="button" <?= $status === 'processing' ? 'disabled' : '' ?>>Wyślij KSeF</button><br><?php endif; ?><span class="badge bg-light text-dark border border-secondary" data-ksef-status="<?= (int)$row['id'] ?>"><?= htmlspecialchars($status ?? 'nie wysłano') ?></span><div class="small mt-1 text-muted" data-ksef-number="<?= (int)$row['id'] ?>"><?= !empty($row['ksef_number']) ? htmlspecialchars($row['ksef_number']) : '' ?></div><div data-ksef-upo="<?= (int)$row['id'] ?>"><?php if (!empty($row['ksef_upo_available'])): ?><a class="btn btn-sm btn-outline-secondary mt-1" href="<?= ROOT ?>/ajax/shipments/<?= (int)$row['id'] ?>/ksef/upo">Pobierz UPO</a><?php endif; ?></div><?php else: ?><span class="text-muted small">bez WDT</span><?php endif; ?></td></tr>
    <?php endforeach; ?>
    </tbody></table></div></div></div></section></div>
<?php $this->view('page_components/footer'); ?>
<script>
function getCMR(id) { downloadPDF('/ajax/cmr-documents/' + id + '/document'); } function getGrouped(id) { downloadPDF('/ajax/shipments/' + id + '/documents/grouped'); } function getWDT(id) { downloadPDF('/ajax/wdt-documents/' + id + '/document'); } function getDiff(id) { downloadPDF('/ajax/difference-documents/' + id + '/document'); }
function updateKsefStatus(shipmentId, submission) { const status=document.querySelector(`[data-ksef-status="${shipmentId}"]`), number=document.querySelector(`[data-ksef-number="${shipmentId}"]`), send=document.querySelector(`[data-ksef-send-button="${shipmentId}"]`), edit=document.querySelector(`[data-ksef-edit-prices="${shipmentId}"]`), upo=document.querySelector(`[data-ksef-upo="${shipmentId}"]`); if(status) status.textContent=submission.status || 'nie wysłano'; if(number) number.textContent=submission.ksef_number || ''; if(upo && submission.upo_available) upo.innerHTML=`<a class="btn btn-sm btn-outline-secondary mt-1" href="<?= ROOT ?>/ajax/shipments/${shipmentId}/ksef/upo">Pobierz UPO</a>`; if(submission.status === 'accepted') { if(send) send.remove(); if(edit) edit.remove(); } else if(send) send.disabled=submission.status === 'processing'; }
function showKsefLoading() { if (typeof Swal !== 'undefined') Swal.fire({title:'Wysyłanie faktury do KSeF', text:'Trwa uwierzytelnianie i przekazywanie faktury. Nie zamykaj tego okna.', allowOutsideClick:false, allowEscapeKey:false, didOpen:()=>Swal.showLoading()}); }
async function confirmKsefSend() { if (typeof Swal === 'undefined') return confirm('Wysłać tę fakturę WDT do KSeF?'); const result=await Swal.fire({title:'Wysłać fakturę do KSeF?', text:'Faktura zostanie przekazana do przetwarzania w wybranym środowisku KSeF.', icon:'question', showCancelButton:true, confirmButtonText:'Wyślij do KSeF', cancelButtonText:'Anuluj', reverseButtons:true}); return result.isConfirmed; }
async function sendToKsef(id) { if (!await confirmKsefSend()) return; showKsefLoading(); try { const r=await fetch('<?= ROOT ?>/ajax/shipments/'+id+'/ksef/send',{method:'POST',headers:{'Content-Type':'application/json'},credentials:'same-origin',body:'{}'}); const d=await r.json(); if(!r.ok||!d.ok) throw new Error(d.message); updateKsefStatus(id,d.submission); showSnack(true,d.message); window.setTimeout(() => refreshKsefStatuses(false), 5000); } catch(e) { showSnack(false,e.message); } finally { if(typeof Swal !== 'undefined') Swal.close(); } }
async function refreshKsefStatuses(showResult=false) { const button=document.getElementById('refresh-ksef-statuses'); if(button) button.disabled=true; try { const r=await fetch('<?= ROOT ?>/ajax/shipments/ksef/refresh-statuses',{method:'POST',headers:{'Content-Type':'application/json'},credentials:'same-origin',body:'{}'}); const d=await r.json(); if(!r.ok||!d.ok) throw new Error(d.message); const x=d.result; (x.updates || []).forEach(item => updateKsefStatus(item.shipmentId,item.submission)); if(showResult) showSnack(true, `Sprawdzono: ${x.checked}; przyjęto: ${x.accepted}; odrzucono: ${x.rejected}; oczekuje: ${x.pending}.`); } catch(e) { if(showResult) showSnack(false,e.message); } finally { if(button) button.disabled=false; } }
function filterTable() { const company = filterCompany.value.toLowerCase(), date = filterDate.value, type = filterType.value; document.querySelectorAll('#generatedDocsTable tbody tr').forEach(row => row.style.display = (!company || row.cells[1].textContent.toLowerCase().includes(company)) && (!date || row.cells[0].textContent.trim() === date) && (!type || (row.dataset.tags || '').split(' ').includes(type)) ? '' : 'none'); }
function clearFilters() { filterCompany.value = ''; filterDate.value = ''; filterType.value = ''; filterTable(); }
filterCompany.addEventListener('input', filterTable); filterDate.addEventListener('input', filterTable); filterType.addEventListener('change', () => { const u = new URL(location.href); filterType.value ? u.searchParams.set('type', filterType.value) : u.searchParams.delete('type'); history.replaceState(null, '', u); filterTable(); });
if (filterType.value) filterTable();
function downloadPpwr(id) { downloadPDF('/ajax/shipments/' + id + '/documents/ppwr'); }
async function createPpwrEvidence(id) { if (!confirm('Dla dostawy bez historycznego snapshotu PPWR raport zostanie odtworzony z bieżącej receptury i profili PPWR. Czy kontynuować?')) return; const response = await fetch('<?= ROOT ?>/ajax/shipments/' + id + '/ppwr-evidence/current-data', {method:'POST',headers:{'Accept':'application/json'},credentials:'same-origin'}), payload = await response.json().catch(() => ({})); if (!response.ok) return alert(payload.message || 'Nie udało się przygotować raportu PPWR.'); const action=document.getElementById('ppwr-action-'+id), status=document.getElementById('ppwr-status-'+id), reconstructed=Boolean(payload.data?.reconstructed); action.className='btn btn-sm btn-outline-primary'; action.textContent='PPWR (PDF)'; action.onclick=()=>downloadPpwr(id); status.className='small '+(reconstructed?'text-warning':'text-success'); status.textContent=reconstructed?'Dane bieżące':'Snapshot wysyłki'; downloadPpwr(id); }
async function createBdoEvidence(id) { if (!confirm('Ewidencja BDO zostanie wyliczona z bieżącej receptury i danych opakowań. Czy kontynuować?')) return; const response=await fetch('<?= ROOT ?>/ajax/shipments/'+id+'/packaging-evidence/current-data',{method:'POST',headers:{'Accept':'application/json'},credentials:'same-origin'}), payload=await response.json().catch(()=>({})); if(!response.ok) return alert(payload.message||'Nie udało się utworzyć ewidencji BDO.'); location.reload(); }
document.addEventListener('DOMContentLoaded', () => refreshKsefStatuses(false));
</script>
